"use client";

import { Line, Text } from "@react-three/drei";
import { useFrame } from "@react-three/fiber";
import { useMemo, useRef } from "react";
import { AdditiveBlending, Color, Group, MathUtils, Vector3 } from "three";
import { useExperience } from "@/store/experience";

export function Signal() {
  const progress = useExperience((state) => state.progress);
  const pulse = useRef<Group>(null);

  const cable = useMemo(
    () => [
      new Vector3(-2.4, -0.55, 5.2),
      new Vector3(-1.1, -0.5, 3.8),
      new Vector3(-0.3, -0.48, 2.2),
      new Vector3(0.45, -0.48, 0.7),
      new Vector3(0.15, -0.46, -1.4),
    ],
    []
  );

  useFrame((_, delta) => {
    if (!pulse.current) return;
    const t = MathUtils.clamp(progress / 0.08, 0, 1);
    const segment = t * (cable.length - 1);
    const index = Math.min(cable.length - 2, Math.floor(segment));
    const local = segment - index;
    pulse.current.position.lerpVectors(cable[index], cable[index + 1], local);
    pulse.current.rotation.y += delta * 0.8;
  });

  return (
    <group>
      <Line points={cable} color="#28241d" lineWidth={3} />
      <group ref={pulse}>
        <mesh>
          <sphereGeometry args={[0.055, 20, 20]} />
          <meshBasicMaterial
            color={new Color("#f4bb67")}
            transparent
            opacity={0.95}
            blending={AdditiveBlending}
          />
        </mesh>
        <pointLight intensity={2.4} distance={2.8} color="#f0aa55" />
      </group>
      <Text position={[0, 0.5, -1.45]} fontSize={0.17} color="#7e7569" anchorX="center">
        SYSTEM 00 / M. PATEL
      </Text>
    </group>
  );
}

"use client";

import { RoundedBox, Text, useTexture } from "@react-three/drei";
import { RepeatWrapping, SRGBColorSpace, Texture } from "three";
