function configureTexture(texture: Texture, repeatX=2, repeatY=2) {
  texture.wrapS=texture.wrapT=RepeatWrapping;
  texture.repeat.set(repeatX,repeatY);
  texture.needsUpdate=true;
  return texture;
}

