];

function flatten(value,path=[],out=[]){
  if(typeof value==="string"&&/^https?:\/\//.test(value)) out.push({path:path.join("/").toLowerCase(),url:value});
  else if(Array.isArray(value)) value.forEach((item,index)=>flatten(item,[...path,String(index)],out));
  else if(value&&typeof value==="object"){
    if(typeof value.url==="string") out.push({path:path.join("/").toLowerCase(),url:value.url});
    for(const [key,item] of Object.entries(value)) flatten(item,[...path,key],out);
  }
  return out;
}

function score(candidate,terms){
  const hay=(candidate.path+" "+candidate.url).toLowerCase();
  return terms.reduce((total,term,index)=>total+(hay.includes(term)?100-index*5:0),0)
    +(hay.includes("1k")?35:0)
    +(hay.includes("2k")?12:0)
    -(hay.includes("4k")?20:0)
    -(hay.includes("8k")?50:0);
}

function best(candidates,terms,extensions){
  return candidates
    .filter((item)=>extensions.some((ext)=>item.url.toLowerCase().includes(ext)))
    .map((item)=>({...item,score:score(item,terms)}))
    .sort((a,b)=>b.score-a.score)[0];
}

async function download(url,destination){
  await mkdir(dirname(destination),{recursive:true});
  const response=await fetch(url,{headers:{"User-Agent":UA}});
  if(!response.ok) throw new Error(`Download failed ${response.status}: ${url}`);
  const buffer=Buffer.from(await response.arrayBuffer());
  await writeFile(destination,buffer);
  console.log(`saved ${destination} (${(buffer.length/1024/1024).toFixed(2)} MB)`);
}

async function files(id){
  const response=await fetch(`${API}/files/${id}`,{headers:{"User-Agent":UA}});
  if(!response.ok) throw new Error(`Poly Haven API ${response.status} for ${id}`);
  return response.json();
}

const credits=[];

for(const asset of requests){
  const tree=await files(asset.id);
  const candidates=flatten(tree);

  if(asset.type==="hdri"){
    const selected=best(candidates,["1k","hdr"],[".hdr"]);
    if(!selected) throw new Error(`No HDR candidate for ${asset.id}`);
    await download(selected.url,join(OUT,"hdri",`${asset.id}_1k.hdr`));
  }else if(asset.type==="model"){
    const direct=best(candidates,["1k","glb"],[".glb"]);
    if(direct){
      await download(direct.url,join(OUT,"models",`${asset.id}.glb`));
    }else{
      const modelDir=join(OUT,"models",asset.id);
      await rm(modelDir,{recursive:true,force:true});
      await mkdir(modelDir,{recursive:true});

      const gltfUrl=`https://dl.polyhaven.org/file/ph-assets/Models/gltf/1k/${asset.id}/${asset.id}_1k.gltf`;
      const response=await fetch(gltfUrl,{headers:{"User-Agent":UA}});

      if(!response.ok){
        console.warn(`No direct 1K glTF package for ${asset.id} (${response.status}); skipping model.`);
      }else{
        const text=await response.text();
        const gltfPath=join(modelDir,`${asset.id}_1k.gltf`);
        await writeFile(gltfPath,text);
        const document=JSON.parse(text);

        const uris=[
          ...(document.buffers||[]).map((entry)=>entry.uri).filter(Boolean),
          ...(document.images||[]).map((entry)=>entry.uri).filter(Boolean),
        ];

        for(const uri of [...new Set(uris)]){
          if(uri.startsWith("data:")) continue;
          const fileName=uri.split("/").pop()?.toLowerCase();
          const apiMatch=candidates.find((item)=>{
            const candidateName=item.url.split("?")[0].split("/").pop()?.toLowerCase();
            return Boolean(fileName && candidateName===fileName);
          });
          const dependencyUrl=apiMatch?.url ?? new URL(uri,gltfUrl).href;
          const dependencyPath=join(modelDir,uri);
          await download(dependencyUrl,dependencyPath);
        }

        console.log(`model ${asset.id}: ${relative(OUT,gltfPath)} with ${uris.length} dependencies`);
      }
    }
  }else{
    const maps=[
      ["diffuse",["diff","diffuse","basecolor"]],
      ["normal",["nor_gl","normal_gl","normal"]],
      ["roughness",["rough","roughness"]],
    ];
    for(const [name,terms] of maps){
      const selected=best(candidates,terms,[".jpg",".png",".webp"]);
      if(!selected){console.warn(`missing ${name} for ${asset.id}`);continue;}
      const ext=(selected.url.match(/\.(jpg|png|webp)(?:\?|$)/i)?.[1]||"jpg").toLowerCase();
      await download(selected.url,join(OUT,"materials",asset.id,`${name}.${ext}`));
    }
  }

  credits.push({
    id:asset.id,
    source:`https://polyhaven.com/a/${asset.id}`,
    author:asset.author,
    license:"CC0",
    chapter:asset.chapter,
    fetchedAt:new Date().toISOString(),
  });
}

await mkdir(OUT,{recursive:true});
await writeFile(join(OUT,"ASSET_CREDITS.json"),JSON.stringify({
  notice:"Assets downloaded via the Poly Haven public API. Powered by Poly Haven.",
  assets:credits,
},null,2)+"\n");

console.log("Poly Haven asset fetch complete.");

