import { readdir, mkdir, rm, stat } from "node:fs/promises";
import { join, extname, basename } from "node:path";
import { spawn } from "node:child_process";

const ROOT="public/assets/models";
await mkdir(ROOT,{recursive:true});

async function run(args){
  await new Promise((resolve,reject)=>{
    const child=spawn("npx",["gltf-transform",...args],{
      stdio:"inherit",
      shell:process.platform==="win32",
    });
    child.on("exit",(code)=>code===0?resolve():reject(new Error(`gltf-transform exited ${code}`)));
  });
}

async function findGltf(dir){
  const entries=await readdir(dir,{withFileTypes:true});
  for(const entry of entries){
    const full=join(dir,entry.name);
    if(entry.isDirectory()){
      const found=await findGltf(full);
      if(found) return found;
    }else if([".gltf",".glb"].includes(extname(entry.name).toLowerCase())){
      return full;
    }
  }
  return null;
}

const entries=await readdir(ROOT,{withFileTypes:true});

for(const entry of entries){
  if(!entry.isDirectory()) continue;
  const modelDir=join(ROOT,entry.name);
  const input=await findGltf(modelDir);
  if(!input){
    console.warn(`No glTF found in ${modelDir}`);
    continue;
  }

  const output=join(ROOT,`${entry.name}.glb`);
  await run([
    "optimize",input,output,
    "--texture-compress","webp",
    "--texture-size","1024",
    "--compress","meshopt",
  ]);

  const bytes=(await stat(output)).size;
  console.log(`optimized ${entry.name} -> ${output} (${(bytes/1024/1024).toFixed(2)} MB)`);
  await rm(modelDir,{recursive:true,force:true});
}

console.log("Model optimization complete.");
